css:
@page { size: A4 portrait; margin: 9mm; }
body { font-family: "Noto Sans", "Noto Naskh Arabic", Arial, sans-serif; font-size: 11px; color: #0f172a; }
.card { border: 1px solid #cbd5e1; border-radius: 14px; overflow: hidden; }
.band { background: linear-gradient(135deg, #0f2e6d 0%, #1f5fbf 100%); color: #fff; padding: 14px 16px; }
.band h1 { margin: 0; font-size: 22px; }
.band .ar { direction: rtl; text-align: right; font-size: 20px; margin-top: 4px; }
.wrap { padding: 12px 14px 16px; }
table { width: 100%; border-collapse: collapse; }
th, td { border: 1px solid #94a3b8; padding: 6px 7px; vertical-align: top; }
th { background: #dbeafe; text-align: left; }
.label-ar { direction: rtl; text-align: right; font-weight: 700; background: #eff6ff; }
.section { margin-top: 12px; }
.muted { color: #475569; font-size: 10px; }
.qr { text-align: center; margin-top: 12px; }
.qr img { width: 110px; height: 110px; }
